 b.essay(3,'توجیه استانداردسازی نماد علمی',s,'چرا 42×10^5 و 4.2×10^6 برابرند ولی فقط دومی نماد علمی استاندارد است؟','انتقال ممیز یک مرتبه به چپ با یک واحد افزایش توان جبران می‌شود؛ ضریب دوم بین یک و ده است.',['برابری مقدارها.','شرط ضریب استاندارد.'])
 b.essay(4,'توجیه استفاده از مزدوج',r,'روش گویا کردن 1/(√5−2) را همراه علت انتخاب مزدوج بنویس.','صورت و مخرج را در √5+2 ضرب می‌کنیم؛ مخرج 5−4=1 و حاصل √5+2 است.',['ضرب صورت و مخرج در یک عبارت یکسان.','اتحاد مزدوج.','نتیجه و ناصفر بودن مخرج.'])
 for q in b.rows:
  adjusted={'تعداد رقم عدد توان ده': 2, 'ریشهٔ سوم منفی با توان\u200cهای مرکب': 3, 'رادیکال و کسری که ساده می\u200cشود': 3}.get(q['objective'])
